import os
import numpy as np
import torch
import torch.nn as nn
import torch.optim as optim
from torch.utils.data import Dataset, DataLoader

# Prepare working directory
working_dir = os.path.join(os.getcwd(), "working")
os.makedirs(working_dir, exist_ok=True)

# Device configuration
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print(f"Using device: {device}")


# Synthetic dataset for multi-turn interactions
class SyntheticDataset(Dataset):
    def __init__(self, size):
        self.data = []
        for _ in range(size):
            prompt = "User prompt for task."
            response = "Model's generated response."
            self.data.append((prompt, response))

    def __len__(self):
        return len(self.data)

    def __getitem__(self, idx):
        return self.data[idx]


# Dataset of uniform distribution
class UniformDataset(Dataset):
    def __init__(self, size, input_dim):
        self.data = torch.rand(size, input_dim).float()

    def __len__(self):
        return len(self.data)

    def __getitem__(self, idx):
        return self.data[idx]


# Dataset of normal distribution
class NormalDataset(Dataset):
    def __init__(self, size, input_dim):
        self.data = torch.randn(size, input_dim).float()

    def __len__(self):
        return len(self.data)

    def __getitem__(self, idx):
        return self.data[idx]


# Defining a polynomial pattern dataset
class PolynomialDataset(Dataset):
    def __init__(self, size, input_dim):
        self.data = torch.linspace(-1, 1, size).view(-1, 1)
        self.labels = self.data**2 + torch.randn(size, 1) * 0.1  # y = x^2 + noise
        self.data = torch.cat([self.data] * input_dim, dim=1)  # Repeat for each feature

    def __len__(self):
        return len(self.labels)

    def __getitem__(self, idx):
        return self.data[idx], self.labels[idx]


# Simple LLM model
class SimpleLLM(nn.Module):
    def __init__(self):
        super(SimpleLLM, self).__init__()
        self.fc = nn.Sequential(
            nn.Linear(10, 64),
            nn.ReLU(),
            nn.Linear(64, 1),  # Output size changed to 1 for regression
        )

    def forward(self, x):
        return self.fc(x)


# Parameters
num_epochs = 5
batch_size = 4
learning_rate = 0.001
momentum_values = [0.0, 0.5, 0.9]  # Momentum hyperparameter values to tune

# Experiment data storage
experiment_data = {
    "input_feature_analysis": {
        "uniform_dataset": {
            "metrics": {"train": []},
            "losses": {"train": []},
            "predictions": [],
            "ground_truth": [],
        },
        "normal_dataset": {
            "metrics": {"train": []},
            "losses": {"train": []},
            "predictions": [],
            "ground_truth": [],
        },
        "polynomial_dataset": {
            "metrics": {"train": []},
            "losses": {"train": []},
            "predictions": [],
            "ground_truth": [],
        },
    },
}

# Experiment with feature type datasets
for feature_type, dataset_class in zip(
    ["uniform", "normal", "polynomial"],
    [UniformDataset, NormalDataset, PolynomialDataset],
):
    print(f"Training with {feature_type} dataset")

    # Instantiate dataset and dataloader
    dataset = dataset_class(size=100, input_dim=10)
    dataloader = DataLoader(dataset, batch_size=batch_size, shuffle=True)

    for momentum in momentum_values:
        print(f"Training with momentum: {momentum}")

        model = SimpleLLM().to(device)
        optimizer = optim.SGD(model.parameters(), lr=learning_rate, momentum=momentum)
        criterion = nn.MSELoss()

        for epoch in range(num_epochs):
            model.train()
            total_loss = 0
            for inputs, labels in dataloader:
                inputs, labels = inputs.to(device), labels.to(device)
                outputs = model(inputs)
                loss = criterion(outputs, labels)

                optimizer.zero_grad()
                loss.backward()
                optimizer.step()

                total_loss += loss.item()

            avg_loss = total_loss / len(dataloader)
            experiment_data["input_feature_analysis"][f"{feature_type}_dataset"][
                "losses"
            ]["train"].append(avg_loss)

            # Simulated UES metric (this should be replaced with a real calculation in practice)
            ues = np.random.rand()
            experiment_data["input_feature_analysis"][f"{feature_type}_dataset"][
                "metrics"
            ]["train"].append(ues)

            print(
                f"Epoch {epoch + 1}/{num_epochs}: loss = {avg_loss:.4f}, UES = {ues:.4f}"
            )

# Save experiment results
np.save(os.path.join(working_dir, "experiment_data.npy"), experiment_data)
